using System;

namespace GrassiNotes;

public static class EmbeddedAssets
{
	private static readonly string VazirRegularBase64 = "";

	private static readonly string VazirSemiBoldBase64 = "";

	private static readonly string VazirBoldBase64 = "";

	private static readonly string AppPngBase64 = "";

	private static readonly string AppIcoBase64 = "";

	public static byte[] VazirRegular => Convert.FromBase64String(VazirRegularBase64);

	public static byte[] VazirSemiBold => Convert.FromBase64String(VazirSemiBoldBase64);

	public static byte[] VazirBold => Convert.FromBase64String(VazirBoldBase64);

	public static byte[] AppPng => Convert.FromBase64String(AppPngBase64);

	public static byte[] AppIco => Convert.FromBase64String(AppIcoBase64);
}
